    b0=hbar[0] if hbar else vbar[0]
    for r in hbar: g[r]=[0]*C
    for c in vbar:
        for r in range(R): g[r][c]=0
    cc=comps2(g)
    mext=max(max(max(x for x,_ in cl)-min(x for x,_ in cl), max(y for _,y in cl)-min(y for _,y in cl))+1 for cl in cc)
    def merge(t):
        tiles=[]
        for cl in sorted(cc,key=lambda cl:min(x for x,_ in cl)):
            r0=min(x for x,_ in cl); c0=min(y for _,y in cl)
            r1=max(x for x,_ in cl); c1=max(y for _,y in cl)
            for tl in tiles:
                xs=[x for x,_ in tl]; ys=[y for _,y in tl]
                if max(r1,max(xs))-min(r0,min(xs))<t and max(c1,max(ys))-min(c0,min(ys))<t:
                    tl.extend(cl); break
            else: tiles.append(list(cl))
        return tiles
    L=None
